parameters.jsCode:
// Form fields sent by the website (contact page + 24/7 widget)
const form = $('Webhook: Contact Form').item.json.body || {};

// Knowledge base text (plain text from /knowledge.txt; strip HTML just in case a page was fetched instead)
let raw = $input.item.json.body ?? $input.item.json.data ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
const knowledge = raw.trim().startsWith('<')
  ? raw.replace(/<script[\s\S]*?<\/script>/gi, '')
       .replace(/<style[\s\S]*?<\/style>/gi, '')
       .replace(/<[^>]+>/g, ' ')
       .replace(/\s+/g, ' ')
  : raw;

return {
  json: {
    user_name: form.name || 'there',
    user_email: form.work_email || form.email || '',
    user_company: form.company || '',
    user_interest: form.interest || '',
    user_message: form.process_takes_most_time || form.message || '',
    source: form.source || 'website',
    page: form.page || '',
    submitted_at: form.submitted_at || $now.toISO(),
    website_context: knowledge.substring(0, 20000)
  }
};

options.systemMessage:
=You are the friendly 24/7 support assistant for AceSoftwares, an automation agency that builds business operating systems, n8n workflows and AI agents in South Africa.

Answer the visitor's message using ONLY the knowledge base below. Be warm, clear and concise (under 150 words). Use Rands. Do not invent prices, dates, clients or promises that are not in the knowledge base.

Reply with exactly NEEDS_HUMAN_AGENT and nothing else when ANY of these apply:
- the answer is not in the knowledge base;
- they want a quote, a demo, a meeting, an audit booking or to start a project;
- it is about an existing account, invoice, outage or broken workflow;
- they are upset, or ask to speak to a person.

KNOWLEDGE BASE:
{{ $json.website_context }}

